import React, { useState } from "react";
import { Link, useLocation } from "react-router-dom";

function Layout({ children }) {
  const location = useLocation();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  const toggleSidebar = () => setSidebarCollapsed(!sidebarCollapsed);

  return (
    <div className={`wrapper ${sidebarCollapsed ? "sidebar-collapse" : ""}`}>
      {/* Navbar */}
      <nav className="main-header navbar navbar-expand navbar-white navbar-light">
        {/* Left navbar links */}
        <ul className="navbar-nav">
          <li className="nav-item">
            <button
              className="nav-link btn btn-light"
              style={{ border: "none", background: "transparent" }}
              onClick={toggleSidebar}
            >
              <i className="fas fa-bars"></i>
            </button>
          </li>
          <li className="nav-item d-none d-sm-inline-block">
            <Link to="/" className="nav-link">
              Home
            </Link>
          </li>
        </ul>
      </nav>

      {/* Sidebar */}
      <aside className="main-sidebar sidebar-dark-primary elevation-4">
        {/* Brand Logo */}
        <Link to="/" className="brand-link">
          <span className="brand-text font-weight-light">ORA Admin</span>
        </Link>

        {/* Sidebar */}
        <div className="sidebar">
          {/* Sidebar Menu */}
          <nav className="mt-2">
            <ul
              className="nav nav-pills nav-sidebar flex-column"
              data-widget="treeview"
              role="menu"
              data-accordion="false"
            >
              <li className="nav-item">
                <Link
                  to="/"
                  className={`nav-link ${
                    location.pathname === "/" ? "active" : ""
                  }`}
                >
                  <i className="nav-icon fas fa-tachometer-alt"></i>
                  <p>Dashboard</p>
                </Link>
              </li>
              <li className="nav-item">
                <Link
                  to="/users"
                  className={`nav-link ${
                    location.pathname === "/users" ? "active" : ""
                  }`}
                >
                  <i className="nav-icon fas fa-users"></i>
                  <p>Users</p>
                </Link>
              </li>
              <li className="nav-item has-treeview">
                <Link
                  to="#"
                  className={`nav-link ${
                    location.pathname.startsWith("/departments") ? "active" : ""
                  }`}
                >
                  <i className="nav-icon fas fa-building"></i>
                  <p>
                    Departments
                    <i className="right fas fa-angle-left"></i>
                  </p>
                </Link>
                <ul className="nav nav-treeview">
                  <li className="nav-item">
                    <Link
                      to="/departments/hr"
                      className={`nav-link ${
                        location.pathname === "/departments/hr" ? "active" : ""
                      }`}
                    >
                      <i className="far fa-circle nav-icon"></i>
                      <p>HR</p>
                    </Link>
                  </li>
                  <li className="nav-item">
                    <Link
                      to="/departments/it"
                      className={`nav-link ${
                        location.pathname === "/departments/it" ? "active" : ""
                      }`}
                    >
                      <i className="far fa-circle nav-icon"></i>
                      <p>IT</p>
                    </Link>
                  </li>
                </ul>
              </li>
            </ul>
          </nav>
          {/* /.sidebar-menu */}
        </div>
        {/* /.sidebar */}
      </aside>

      {/* Content Wrapper */}
      <div className="content-wrapper">
        <section className="content-header">
          <div className="container-fluid">
            {children}
          </div>
        </section>
      </div>
    </div>
  );
}

export default Layout;
